def decode_anchor_key(j, path: str) -> AnchorKey:
    m = obj(j, path)
    only_fields(m, ("key", "suite", "public_key"), path)
    return AnchorKey(key=req(m, "key", path, dec_id), suite=req(m, "suite", path, dec_id), public_key=req(m, "public_key", path, dec_string))


